import csv
import io
import re
from typing import List, Dict, Tuple, Optional


EXPECTED_WIDTH = 9


def _fallback_parse(raw_csv: str) -> List[List[str]]:
    rows: List[List[str]] = []
    row: List[str] = []
    field: List[str] = []
    in_quotes = False
    at_field_start = True
    i = 0
    length = len(raw_csv)

    while i < length:
        ch = raw_csv[i]

        if in_quotes:
            if ch == '"':
                if i + 1 < length and raw_csv[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                in_quotes = False
                i += 1
                continue
            field.append(ch)
            i += 1
            continue

        if ch == '"' and at_field_start:
            in_quotes = True
            at_field_start = False
            i += 1
            continue

        if ch == ",":
            row.append("".join(field))
            field = []
            at_field_start = True
            i += 1
            continue

        if ch == "\r" or ch == "\n":
            row.append("".join(field))
            field = []
            rows.append(row)
            row = []
            at_field_start = True
            if ch == "\r" and i + 1 < length and raw_csv[i + 1] == "\n":
                i += 2
            else:
                i += 1
            continue

        field.append(ch)
        at_field_start = False
        i += 1

    if field or row or (length > 0 and raw_csv[-1] == ","):
        row.append("".join(field))
        rows.append(row)

    return rows


def _read_records(raw_csv: str) -> List[List[str]]:
    try:
        csv.field_size_limit(100000000)
    except (OverflowError, ValueError):
        pass

    try:
        reader = csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            skipinitialspace=False,
            strict=False,
        )
        rows = [list(row) for row in reader]
    except (csv.Error, UnicodeError):
        rows = _fallback_parse(raw_csv)

    if rows and rows[0]:
        rows[0][0] = rows[0][0].lstrip("\ufeff")
    return rows


def _header_likelihood(row: List[str]) -> float:
    if not row:
        return -100.0

    score = 0.0
    nonempty = 0
    distinct = set()

    for value in row:
        text = value.strip()
        if not text:
            score -= 1.0
            continue

        nonempty += 1
        distinct.add(text.lower())

        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9 _./()'\-]*", text):
            score += 2.0
        if re.search(r"[A-Za-z]", text):
            score += 0.5
        if re.fullmatch(r"[-+]?\d+(?:[./:-]\d+)+", text):
            score -= 2.5
        if re.match(r"(?i)^[a-z][a-z0-9+.-]*://", text):
            score -= 3.0

    if nonempty == len(row):
        score += 2.0
    if len(distinct) == nonempty:
        score += 1.0
    return score


def _find_header_index(rows: List[List[str]]) -> int:
    if not rows:
        return 0

    exact_candidates = [i for i, row in enumerate(rows) if len(row) == EXPECTED_WIDTH]
    candidates = exact_candidates if exact_candidates else list(range(len(rows)))

    best_index = candidates[0]
    best_score = float("-inf")

    for index in candidates:
        row = rows[index]
        score = _header_likelihood(row)
        score -= abs(len(row) - EXPECTED_WIDTH) * 5.0
        score -= min(index, 1000) * 0.01

        following = rows[index + 1:index + 21]
        for distance, candidate in enumerate(following, 1):
            weight = 1.0 / (1.0 + distance * 0.08)
            if len(candidate) == EXPECTED_WIDTH:
                score += 1.5 * weight
            elif candidate:
                score -= min(abs(len(candidate) - EXPECTED_WIDTH), 3) * 0.3 * weight

        if score > best_score:
            best_score = score
            best_index = index

    return best_index


def _normalize_header(row: List[str]) -> List[str]:
    result = list(row)
    if len(result) < EXPECTED_WIDTH:
        result.extend([""] * (EXPECTED_WIDTH - len(result)))
    elif len(result) > EXPECTED_WIDTH:
        result = result[:EXPECTED_WIDTH - 1] + [
            ",".join(result[EXPECTED_WIDTH - 1:])
        ]
    return result


def _value_kind(value: str) -> str:
    text = value.strip()
    if not text:
        return "blank"
    if re.match(r"(?i)^[a-z][a-z0-9+.-]*://", text) or re.match(
        r"(?i)^www\.", text
    ):
        return "url"
    if re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", text):
        return "email"
    if re.fullmatch(r"\d{1,4}[-/.]\d{1,2}[-/.]\d{1,4}", text):
        return "date"
    if re.fullmatch(r"\d{1,2}:\d{2}(?::\d{2})?(?:\s*[AaPp][Mm])?", text):
        return "time"
    if re.fullmatch(r"[-+]?\d+", text):
        return "integer"
    if re.fullmatch(r"[$€£¥]\s*[-+]?(?:\d+(?:,\d{3})*|\d*)(?:\.\d+)?", text):
        return "currency"
    if re.fullmatch(r"[-+]?(?:\d+(?:,\d{3})*|\d*)(?:\.\d+)%", text):
        return "percent"
    if re.fullmatch(r"[-+]?(?:\d+(?:,\d{3})*|\d*)(?:\.\d+)", text):
        return "number"
    return "text"


def _header_kind(header: str) -> Optional[str]:
    name = re.sub(r"[^a-z0-9]+", " ", header.lower()).strip()
    words = set(name.split())

    if "url" in words or "uri" in words or "link" in words or "website" in words:
        return "url"
    if "email" in words or "e-mail" in header.lower():
        return "email"
    if "date" in words:
        return "date"
    if "time" in words:
        return "time"
    if words.intersection({"qty", "quantity", "count", "units", "number"}):
        return "integer"
    if words.intersection({"price", "cost", "amount", "total", "charge"}):
        return "currency"
    if words.intersection({"percent", "percentage", "rate"}):
        return "percent"
    return None


def _build_profiles(
    header: List[str], rows: List[List[str]]
) -> List[Dict[str, object]]:
    profiles: List[Dict[str, object]] = []

    for column in range(EXPECTED_WIDTH):
        values = [
            row[column]
            for row in rows
            if len(row) == EXPECTED_WIDTH
        ]

        kinds: Dict[str, int] = {}
        lengths: List[int] = []
        blanks = 0

        for value in values:
            kind = _value_kind(value)
            kinds[kind] = kinds.get(kind, 0) + 1
            if kind == "blank":
                blanks += 1
            else:
                lengths.append(len(value.strip()))

        lengths.sort()
        median_length = lengths[len(lengths) // 2] if lengths else 0

        dominant = "text"
        dominant_count = -1
        for kind, count in kinds.items():
            if kind != "blank" and count > dominant_count:
                dominant = kind
                dominant_count = count

        profiles.append(
            {
                "count": len(values),
                "blanks": blanks,
                "median": median_length,
                "dominant": dominant,
                "hint": _header_kind(header[column]),
            }
        )

    return profiles


def _compatibility(value: str, profile: Dict[str, object]) -> float:
    kind = _value_kind(value)
    count = int(profile["count"])
    blanks = int(profile["blanks"])
    median = int(profile["median"])
    dominant = str(profile["dominant"])
    hint = profile["hint"]

    if kind == "blank":
        if count and blanks * 2 >= count:
            return 3.0
        if count and blanks == 0:
            return -2.0
        return 0.0

    score = 0.0

    if hint is not None:
        if kind == hint:
            score += 6.0
        elif hint == "currency" and kind in ("number", "integer"):
            score += 1.0
        elif hint == "integer" and kind == "number":
            score += 1.0
        else:
            score -= 4.0

    specialized = {
        "url", "email", "date", "time", "integer",
        "number", "currency", "percent"
    }

    if dominant in specialized:
        if kind == dominant:
            score += 4.0
        elif dominant in ("integer", "number") and kind in ("integer", "number"):
            score += 1.5
        elif dominant == "currency" and kind in ("number", "integer"):
            score += 0.5
        else:
            score -= 3.0
    elif kind in specialized:
        score -= 0.5
    else:
        score += 1.0

    if count and blanks * 4 >= count * 3:
        score -= 2.0

    value_length = len(value.strip())
    if median and value_length:
        if value_length > median * 4 or median > value_length * 4:
            score -= 2.0
        elif value_length <= median * 2 and median <= value_length * 2:
            score += 1.0

    return score


def _reduce_extreme_width(
    row: List[str], profiles: List[Dict[str, object]]
) -> List[str]:
    if len(row) <= EXPECTED_WIDTH:
        return row

    target = 0
    target_score = -1
    for index, profile in enumerate(profiles):
        median = int(profile["median"])
        hint = profile["hint"]
        score = median
        if hint in ("url", "date", "time", "integer", "currency", "number"):
            score -= 1000
        if score > target_score:
            target_score = score
            target = index

    merge_count = len(row) - EXPECTED_WIDTH + 1
    start = min(target, len(row) - merge_count)
    return (
        row[:start]
        + [",".join(row[start:start + merge_count])]
        + row[start + merge_count:]
    )


def _repair_row(
    row: List[str], profiles: List[Dict[str, object]]
) -> List[str]:
    if len(row) == EXPECTED_WIDTH:
        return list(row)

    source = list(row)
    if len(source) > EXPECTED_WIDTH + 40:
        source = _reduce_extreme_width(source, profiles)

    source_count = len(source)
    width = EXPECTED_WIDTH
    states: Dict[Tuple[int, int], Tuple[float, List[str]]] = {
        (0, 0): (0.0, [])
    }

    for column in range(width):
        next_states: Dict[Tuple[int, int], Tuple[float, List[str]]] = {}

        for (used, current_column), (score, path) in states.items():
            if current_column != column:
                continue

            profile = profiles[column]
            blank_ratio_high = (
                int(profile["count"]) > 0
                and int(profile["blanks"]) * 2 >= int(profile["count"])
            )
            missing_penalty = -2.0 if blank_ratio_high else -6.0
            missing_key = (used, column + 1)
            missing_value = (score + missing_penalty, path + [""])
            old = next_states.get(missing_key)
            if old is None or missing_value[0] > old[0]:
                next_states[missing_key] = missing_value

            remaining = source_count - used
            if remaining <= 0:
                continue

            if column == width - 1:
                maximum = remaining
                minimum = remaining
            else:
                maximum = remaining
                minimum = 1

            for take in range(minimum, maximum + 1):
                value = ",".join(source[used:used + take])
                merge_penalty = (take - 1) * 2.0
                candidate_score = (
                    score
                    + _compatibility(value, profile)
                    - merge_penalty
                )
                key = (used + take, column + 1)
                candidate = (candidate_score, path + [value])
                old = next_states.get(key)
                if old is None or candidate_score > old[0]:
                    next_states[key] = candidate

        states = next_states

    result = states.get((source_count, width))
    if result is not None:
        return result[1]

    fallback = list(source[:width])
    if len(fallback) < width:
        fallback.extend([""] * (width - len(fallback)))
    elif len(source) > width:
        fallback[-1] = ",".join(source[width - 1:])
    return fallback


def parse_csv(raw_csv: str):
    records = _read_records(raw_csv)
    if not records:
        return {"columns": [], "rows": []}

    header_index = _find_header_index(records)
    columns = _normalize_header(records[header_index])
    data_rows = records[header_index + 1:]
    profiles = _build_profiles(columns, data_rows)
    rows = [_repair_row(row, profiles) for row in data_rows]

    return {"columns": columns, "rows": rows}
